schema=json.load(open(REPO/'generate/pipeline/pedagogical-variation.schema.json'))
def valid(v,s,path='$'):
 if 'enum' in s:assert v in s['enum'],path
 typ=s.get('type')
 if typ=='object':
  assert isinstance(v,dict),path
  assert set(s.get('required',[]))<=set(v),path
  if s.get('additionalProperties') is False:assert set(v)<=set(s['properties']),path
  for k,z in v.items():
   if k in s.get('properties',{}):valid(z,s['properties'][k],path+'.'+k)
 elif typ=='array':
  assert isinstance(v,list) and len(v)>=s.get('minItems',0),path
  for i,z in enumerate(v):valid(z,s['items'],path+'['+str(i)+']')
 elif typ=='string':assert isinstance(v,str) and len(v)>=s.get('minLength',0),path
 elif typ in ('integer','number'):
  assert type(v) in ((int,) if typ=='integer' else (int,float)),path
  assert v>=s.get('minimum',float('-inf')) and v<=s.get('maximum',float('inf')),path
